body{
    font-family: $regularfont ;
    font-size: rem(14px); 
   
}

h1,h2,h3,h4,h5,h6{
    font-family: $boldfont ; 
}
 


.form-control{
        
    background: lighten($deep_navy,65.7%);
    padding: rem(13px);
    &:not(.is-invalid):not(.is-valid):not(:focus){
        border-color: transparent;
    }
    @include placeholder{
        color:lighten($deep_navy,36%);
    }
   
} 


.section-content{
    padding: rem(100px) 0;
    position: relative;
    @include media-breakpoint-down(sm){
        padding: rem(30px) 0;
    }
}

.btn-send{
    background: $mainColor;
    color: #fff;
    font-size: rem(14px); 

    &:focus{
        box-shadow: 0 0 0 2px rgba($mainColor,.5); 
    }

    svg{
        rect{
            fill: #fff;
        }
    }
} 
.modal.fade .modal-dialog {
    transform:  scale(0.9);
}
.modal.show .modal-dialog{
    transform:   scale(1);  
} 

.validation-summary-errors{
    ul{
        margin: 0;
    }
}
//-----------------------------------------------------------
//-----------------------------------------------------------
//-----------------------------------------------------------
.section{  
    padding: rem(70px) 0;
}

.not-animated{
    opacity: 0;
}
.animated-item{
    opacity: 1;
    animation-duration: .7s;
    animation-fill-mode: both;
}






.section_title{
        position: relative;
        margin-bottom : rem(80px);
             &:before{
                @include absolute(top $left ,rem(-65px) 0 );
                content: attr(data-content);
                z-index: -1;
                font-size: 8.5vw;
                font-family: $boldfont;
                white-space: nowrap;
                width:100%;
                overflow: hidden;
                text-align: center;
                color: darken(#fff,3%);
                @include media-breakpoint-down(sm) {
                   content: none;
                 }
            } 
        
    h2{
        font-size: rem(33px);
        font-family:  $regularfont;
        margin-bottom:rem(20px);
        letter-spacing: 1px;
        text-transform: uppercase;
        color: darken($deep_navy,5%);
        position: relative;
        strong{
            font-weight: normal; 
            display: inline-block;
            position: relative;
            padding-bottom:rem(20px);  
            &:before{
                content: "";
                @include size(100%,2px);
                background: darken(#fff,40%); 
                @include absolute(bottom left , 0 );
                transform: scaleX(0.4);
            }
            &:after{
                content: "";
                @include square(8px);
                @include absolute(bottom $left , -2px #{calc(50% - 4px)});
                background: $mainColor;
                border-radius: 50%;
                box-shadow: 0  0 0 8px #fff , 15px 1px 0 -1px darken(#fff,40%) , -15px 1px 0 -1px  darken(#fff,40%);
            } 

            &.gray{
                &:after{
                    box-shadow: 0  0 0 8px darken(#fff,3%)  , 15px 1px 0 -1px darken(#fff,40%) , -15px 1px 0 -1px  darken(#fff,40%);
                } 
            }
        } 
      
    }
    p{
        font-size: rem(18px);
        letter-spacing: 1px;
        margin: 15px auto;
        color: lighten( #000000,40%);
        @include media-breakpoint-up(sm) {
             width: 90%;
          }
    }

    &.gray-bg{
        z-index:1;
          &:before{
                color: darken(#fff,1%);
            } 
    }


    @include media-breakpoint-only(xs){
        h2{
            font-size: rem(24px);
        }
        P{
            font-size: rem(14px);  
        }
    }
}

.btn-orange{
    background: $orange;
    color: #fff;
    &:hover{
        background: lighten($orange,5%);
    }
}

.back-to-top{
    @include fixed(bottom $right, 35px 10px );
    @include square(45px);
     background: #fff;
    color: #000;
    text-align: center;
    line-height: 40px;
    display: none;
    z-index: 15000; 
    border-radius: 5px;
    box-shadow: 0px 5px 30px rgba(0,0,0,0.05);
    svg{
        margin-top: 8px;
        @include square(25px);
        path{
            fill: #000;
        }
    }
    @include media-breakpoint-only(xs){
        bottom: 45px;
    }
}
.mt150{
  @include media-breakpoint-up(md){

    margin-top: rem(200px);
  }
}

.accessory {
    height:1px;
    background: #f7f7f7;
    background: linear-gradient(to right, #f7f7f7 0%,#a5a5a5 51%,#f7f7f7 100%);
    position: relative;
    border: 0;
    margin: rem(100px) auto;
    max-width: 100%;
    background-position: 50%;
    box-sizing: border-box;
    @include media-breakpoint-only(xs){
        margin: 25px auto;
    }
  }


.title-border-bottom{
    h1,h2,h3,h4,h5,h6{
        border-bottom: 1px solid rgba(#000,.1);
        margin-bottom: rem(25px);
        span{
            display: inline-block;
            margin-bottom: -1px;
            border-bottom: 1px solid $mainColor;
            padding-bottom: rem(15px);
        }
    }
}

.bb-title{
    border-bottom: 1px solid rgba(#000,.1);
    margin-bottom: rem(25px);
    span,a{
        color: #444;
        display: inline-block;
        margin-bottom: -1px;
        border-bottom: 1px solid $mainColor;
        padding-bottom: rem(15px);
    }
    a:hover{
        text-decoration: none
    }
}

   

.cu-title{
    position: relative;
    margin-bottom: rem(25px);
    color: darken($deep_navy,5%);
    strong,span{
        display: inline-block;
        position: relative;
        text-shadow: 2px -1px 0 #fff;
        z-index: 1;
        &:before{
            content: '';
            @include absolute(top  $left , 0  -4px);
            @include size(30px ,15px);
            background: lighten($mainColor ,10%);
            z-index: -1;
            transform: rotate(-30deg);
        }
    }
}

@include media-breakpoint-down(sm){
    .text-xs-center{
        text-align: center; 
    }
}
