.ares.tparrows {
  cursor: pointer;
  background: #fff;
  min-width: 60px;
  min-height: 60px;
  position: absolute;
  display: block;
  z-index: 100;
  border-radius: 50%
}

.ares.tparrows:before {
  font-family: "revicons";
  font-size: 25px;
  color: #aaa;
  display: block;
  line-height: 60px;
  text-align: center;
  -webkit-transition: color .3s;
  -moz-transition: color .3s;
  transition: color .3s;
  z-index: 2;
  position: relative
}

.ares.tparrows.tp-leftarrow:before {
  content: "\e81f"
}

.ares.tparrows.tp-rightarrow:before {
  content: "\e81e"
}

.ares.tparrows:hover:before {
  color: #000
}

.ares .tp-title-wrap {
  position: absolute;
  z-index: 1;
  display: inline-block;
  background: #fff;
  min-height: 60px;
  line-height: 60px;
  top: 0;
  margin-left: 30px;
  border-radius: 0 30px 30px 0;
  overflow: hidden;
  -webkit-transition: -webkit-transform .3s;
  transition: transform .3s;
  transform: scaleX(0);
  -webkit-transform: scaleX(0);
  transform-origin: 0 50%;
  -webkit-transform-origin: 0 50%
}

.ares.tp-rightarrow .tp-title-wrap {
  right: 0;
  margin-right: 30px;
  margin-left: 0;
  -webkit-transform-origin: 100% 50%;
  border-radius: 30px 0 0 30px
}

.ares.tparrows:hover .tp-title-wrap {
  transform: scaleX(1) scaleY(1);
  -webkit-transform: scaleX(1) scaleY(1)
}

.ares .tp-arr-titleholder {
  position: relative;
  -webkit-transition: -webkit-transform .3s;
  transition: transform .3s;
  transform: translateX(200px);
  text-transform: uppercase;
  color: #000;
  font-weight: 400;
  font-size: 14px;
  line-height: 60px;
  white-space: nowrap;
  padding: 0 20px;
  margin-left: 10px;
  opacity: 0
}

.ares.tp-rightarrow .tp-arr-titleholder {
  transform: translateX(-200px);
  margin-left: 0;
  margin-right: 10px
}

.ares.tparrows:hover .tp-arr-titleholder {
  transform: translateX(0px);
  -webkit-transform: translateX(0px);
  transition-delay: .1s;
  opacity: 1
}

.ares.tp-bullets:before {
  content: " ";
  position: absolute;
  width: 100%;
  height: 100%;
  background: transparent;
  padding: 10px;
  margin-left: -10px;
  margin-top: -10px;
  box-sizing: content-box
}

.ares .tp-bullet {
  width: 13px;
  height: 13px;
  position: absolute;
  background: #e5e5e5;
  border-radius: 50%;
  cursor: pointer;
  box-sizing: content-box
}

.ares .tp-bullet:hover,
.ares .tp-bullet.selected {
  background: #fff
}

.ares .tp-bullet-title {
  position: absolute;
  color: #888;
  font-size: 12px;
  padding: 0 10px;
  font-weight: 600;
  right: 27px;
  top: -4px;
  background: #fff;
  background: rgba(255, 255, 255, 0.75);
  visibility: hidden;
  transform: translateX(-20px);
